SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, COUNT(p.subject_id) AS total_admissions, AVG(p.dod - p.admittime) AS average_length_of_stay FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.admissions a ON p.subject_id = a.subject_id JOIN physionet-data.mimiciv_3_1_hosp.diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND CAST(p.anchor_age AS INT) BETWEEN 70 AND 80 AND d.icd_code = '415080' AND a.dischtime - a.admittime < 8 GROUP BY p.subject_id HAVING COUNT(p.dod) > 0 ORDER BY average_length_of_stay NULLS LAST;